DECLARE @school_year smallint=?,@grade_code varchar(2)=?,@class_code varchar(9)=?,@class_name nvarchar(36)=?,@valid_from date=?,@valid_to date=?,@capacity int=?,@display_order int=?,@is_active bit=?,@remarks nvarchar(240)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @saved TABLE(id bigint); INSERT INTO dbo.m_class(school_year,grade_code,class_code,class_name,valid_from,valid_to,capacity,display_order,is_active,remarks,grade_category,created_at,created_by,updated_at,updated_by,row_version) OUTPUT INSERTED.class_id INTO @saved VALUES (@school_year,@grade_code,@class_code,@class_name,@valid_from,@valid_to,@capacity,@display_order,@is_active,@remarks,'GRADE',@now,@actor,@now,@actor,1); SELECT id FROM @saved;
